#!/usr/bin/env bash
# Generated by gitopsify. Applies the prod environment in reconciliation
# order with server-side apply. Extra arguments go to kubectl, for example:
#   ./apply-prod.sh --context prod
set -euo pipefail
cd "$(dirname "$0")"

build() {
  if command -v kustomize >/dev/null 2>&1; then
    kustomize build "$@"
  else
    kubectl kustomize "$@"
  fi
}

apply() {
  local dir=$1
  shift
  echo ">> ${dir}"
  build "${dir}" | kubectl apply --server-side --field-manager=gitopsify --force-conflicts -f - "$@"
}

apply_helm() {
  local dir=$1
  shift
  echo ">> ${dir} (helm)"
  build --enable-helm "${dir}" | kubectl apply --server-side --field-manager=gitopsify --force-conflicts -f - "$@"
}

# wave -30
apply apps/crds/envs/prod "$@"
kubectl wait --for=condition=Established crd --all --timeout=120s "$@"

# wave -20
apply apps/namespaces/envs/prod "$@"

# wave -10
apply apps/cluster/envs/prod "$@"

# wave 0
apply_helm apps/inhouse/envs/prod "$@"
apply apps/payments/envs/prod "$@"
apply_helm apps/podinfo/envs/prod "$@"
apply apps/shop/envs/prod "$@"
